// publish only on change, plus a full refresh every 30 s (so retained topics never go stale)
const names = ["fault_latch", "system_run", "s0_idle", "s1_transport", "s2_load", "s3_turn", "s4_unload", "s5_delivered", "box_tall", "box_short", "height_ok", "side_seen"];
const prefix = 'sorting/status/state/';
const last = context.get('last') || {};
const now = Date.now();
const force = now - (context.get('t') || 0) > 30000;
if (force) context.set('t', now);
const out = [];
const send = (topic, val) => {
    const p = (typeof val === 'boolean') ? (val ? 'true' : 'false') : String(val);
    if (force || last[topic] !== p) { last[topic] = p; out.push({topic: topic, payload: p}); }
};
names.forEach((n, i) => { if (msg.payload[i] !== undefined) send(prefix + n, !!msg.payload[i]); });
const b = {}; names.forEach((n, i) => b[n] = !!msg.payload[i]);
const steps = [['s0_idle','S0 Idle'],['s1_transport','S1 Transport'],['s2_load','S2 Load'],['s3_turn','S3 Turn'],['s4_unload','S4 Unload'],['s5_delivered','S5 Delivered']];
const step = steps.find(s => b[s[0]]);
send('sorting/status/step', step ? step[1] : '-');
send('sorting/status/box_height', b.box_tall ? 'Tall' : (b.box_short ? 'Short' : '-'));
send('sorting/status/mode', b.fault_latch ? 'FAULT / E-STOP' : (b.system_run ? 'RUNNING' : 'STOPPED'));
context.set('last', last);
return out.length ? [out] : null;

const map = {start: 8192, stop: 8193, reset: 8194};   // Cmd_Start, Cmd_Stop, Cmd_Reset (%MX0.0-0.2 = coil 8192-8194)
const cmd = String(msg.topic).split('/').pop();
const p = String(msg.payload).toLowerCase();
if (!(cmd in map) || !['1', 'true', 'on'].includes(p)) return null;
const addr = map[cmd];
const w = v => ({payload: {value: v, fc: 5, unitid: 1, address: addr, quantity: 1}});
node.send(w(true));
setTimeout(() => node.send(w(false)), 300);
node.status({fill: 'green', shape: 'dot', text: 'cmd ' + cmd});
return null;
